interface StatCardProps {
  title: string;
  value: string;
  change: string;
  positive?: boolean;
  href?: string;
}

const StatCard: React.FC<StatCardProps> = ({ title, value, change, positive = true, href }) => {
  const sparkData = useMemo(() => {
    const dates = [
      "2025-01-01",
      "2025-01-02",
      "2025-01-03",
      "2025-01-04",
      "2025-01-05",
      "2025-01-06",
      "2025-01-07",
    ];
    const rand = (min: number, max: number) => Math.floor(Math.random() * (max - min + 1)) + min;
    return dates.map(
      (date) =>
        ({
          date,
          "Current period": rand(0, 1500),
        }) as { date: string; "Current period": number },
    );
  }, []);

  return (
    <Card
      minWidth={12}
      href={href}
      paddingX="20"
      paddingTop="20"
      paddingBottom="80"
      radius="l"
      fillWidth
      direction="column"
      border
      background="transparent"
    >
      <LineChart
        pointerEvents="none"
        position="absolute"
        opacity={30}
        left="0"
        bottom="0"
        height={6}
        border="transparent"
        axis="none"
        tooltip={false}
        legend={{ display: false }}
        grid="none"
        series={[{ key: "Current period", color: positive ? "green" : "red" }]}
        data={sparkData}
      />
      <Column fillWidth gap="12">
        <Row vertical="center" gap="12">
          <Row fillWidth textVariant="label-default-s" onBackground="neutral-medium">
            {title}
          </Row>
          <Row gap="8" vertical="center" onBackground={positive ? "success-weak" : "danger-weak"}>
            <Icon size="xs" name={positive ? "trendUp" : "trendDown"} />
            <Text variant="body-default-xs">{change}</Text>
          </Row>
        </Row>
        <Heading variant="display-strong-xs">{value}</Heading>
      </Column>
    </Card>
  );
};

